if(PHP_SAPI!=='cli'||getenv('ISSUERS_BROWSER_DB_NAME')!=='argws_upgrade_ci')exit(2);
define('FCPATH',dirname(__DIR__,2).'/');define('BASEPATH',FCPATH.'system/');define('APPPATH',FCPATH.'application/');require APPPATH.'config/app-config.php';
if(APP_DB_NAME!=='argws_upgrade_ci'||!preg_match('/^(127\.0\.0\.1|argws-crm-provision-db-[0-9]+)(:[0-9]+)?$/D',APP_DB_HOSTNAME))exit(2);
$pdo=new PDO('mysql:host='.str_replace(':',';port=',APP_DB_HOSTNAME).';dbname='.APP_DB_NAME.';charset=utf8mb4',APP_DB_USERNAME,APP_DB_PASSWORD,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$pdo->exec('SET SESSION TRANSACTION READ ONLY');$pdo->beginTransaction();register_shutdown_function(static function()use($pdo){if($pdo->inTransaction())$pdo->rollBack();});
$version=(int)$pdo->query('SELECT version FROM tblmigrations')->fetchColumn();$config=[];require APPPATH.'config/migration.php';$target=$config['migration_version']??null;if(!is_int($target)||(int)$version!==$target||$target<444)throw new RuntimeException('Exact trusted current native444 or later required');
$identity=$pdo->query('SELECT master_staff_id,primary_issuer_id FROM tblissuers_installation_identity WHERE id=1')->fetch(PDO::FETCH_ASSOC);$owners=['a'=>(int)$pdo->query("SELECT id FROM tblissuers_registry WHERE tax_id='11222333000181'")->fetchColumn(),'b'=>(int)$pdo->query("SELECT id FROM tblissuers_registry WHERE tax_id='52998224725'")->fetchColumn(),'primary'=>(int)$identity['primary_issuer_id']];if(min($owners)<1)throw new RuntimeException('Native companies required');
function queryRows($pdo,$sql,$bind=[]){$q=$pdo->prepare($sql);$q->execute($bind);return$q->fetchAll(PDO::FETCH_ASSOC);}
$mode=$argv[1]??'inspect';
if($mode==='inspect'){$out=['owners'=>$owners,'actor'=>(int)$identity['master_staff_id'],'contacts'=>[],'native_marker'=>$version,'expected_marker'=>$target,'read_only'=>true,'legacy_order'=>$pdo->query("SELECT value FROM tbloptions WHERE name='ticket_replies_order'")->fetchColumn()];foreach(['a','b']as$letter){$rows=queryRows($pdo,'SELECT c.userid client_id,k.id contact_id,k.email FROM tblclients c JOIN tblissuers_clients x ON x.client_id=c.userid AND x.owner_issuer_id=? JOIN tblcontacts k ON k.userid=c.userid AND k.active=1 WHERE c.company=? ORDER BY k.id LIMIT 1',[$owners[$letter],'Synthetic portal client '.$letter]);if(count($rows)!==1)throw new RuntimeException('Run actual native portal onboarding fixture first');$out['contacts'][$letter]=$rows[0];}echo json_encode($out,JSON_THROW_ON_ERROR);exit;}
