if($mode==='ticket'){$issuer=filter_var($argv[2]??'',FILTER_VALIDATE_INT);$id=filter_var($argv[3]??'',FILTER_VALIDATE_INT);if(!in_array($issuer,$owners,true)||!$id)exit(2);$row=queryRows($pdo,'SELECT id FROM tblcompany_tickets WHERE issuer_id=? AND id=?',[$issuer,$id]);if(count($row)!==1)throw new RuntimeException('Owned ticket required');echo json_encode(queryRows($pdo,'SELECT id,body FROM tblcompany_ticket_replies WHERE issuer_id=? AND ticket_id=? ORDER BY id',[$issuer,$id]),JSON_THROW_ON_ERROR);exit;}exit(2);
